/** The package's version, from `package.json`. Defined by `.storybook/main.ts`, so only the handbook has it. */
declare const __PACKAGE_VERSION__: string

/** Each release's date by version (`0.1.0` → `2026-11-04`), from the git tags. Defined by `.storybook/main.ts`. */
declare const __RELEASE_DATES__: Record<string, string>
